#include <stdio.h>
#define main prog_main
#include "program.c"
#undef main
static unsigned ref_adler(unsigned seed)
{
    unsigned char d[16];
    unsigned i, a = seed & 65535u, b = (seed >> 16) & 65535u;
    for (i = 0; i < 16; ++i)
    {
        unsigned sel = (i + seed) % 7u;
        d[i] = sel == 0 ? '/' : sel == 1 ? '~' : (unsigned char)('a' + (i * 5u + seed) % 26u);
    }
    for (i = 0; i < 16; ++i) { a = (a + d[i]) % 65521u; b = (b + a) % 65521u; }
    return (b << 16) | a;
}
int main(void)
{
    unsigned seeds[] = {5u, 0u, 0x12345678u, 65521u};
    unsigned i;
    int fails = 0;
    View saved;
    unsigned char tmp[16];
    for (i = 0; i < 16; ++i) tmp[i] = (unsigned char)(i * 3u + 1u);
    for (i = 0; i < 4; ++i)
    {
        if ((unsigned)evaluate(seeds[i]) != ref_adler(seeds[i])) ++fails;
    }
    prepare(&saved, tmp, 7u);
    for (i = 0; i < 16; ++i) tmp[i] = 0;
    for (i = 0; i < 16; ++i)
    {
        if (byte_at(&saved, i) != (unsigned char)(i * 3u + 1u)) ++fails;
    }
    printf("fails=%d\n", fails);
    return fails;
}
EOF
